INSERT INTO compatibility_rules (rule_code, domain, title, description, condition_json, severity, recommended_action, is_active) VALUES ('ELEC_VOLTAGE_IN', 'ELECTRONICS', 'Indian 230V Socket Voltage Check', 'Flags 110V/120V appliances incompatible with Indian 230V/50Hz outlets.', '{"requiredVoltage":"230V"}', 'INCOMPATIBLE', 'Use a step-down transformer or pick a 230V variant.', TRUE);
INSERT INTO compatibility_rules (rule_code, domain, title, description, condition_json, severity, recommended_action, is_active) VALUES ('ELEC_WATTAGE_SURGE', 'ELECTRONICS', 'Power Strip Load Safety Check', 'Prevents plugging combined >1500W appliances into standard 6A surge strips.', '{"maxStripWatts":1500}', 'INCOMPATIBLE', 'Plug 1500W-2000W heating appliances directly into a 16A wall socket.', TRUE);
INSERT INTO compatibility_rules (rule_code, domain, title, description, condition_json, severity, recommended_action, is_active) VALUES ('ELEC_PLUG_TYPE', 'ELECTRONICS', 'Plug Pin Compatibility', 'Warns when US/UK plugs are mixed without a travel adapter.', '{"plug":"Type D/M"}', 'WARNING', 'Add a universal travel adapter.', TRUE);
INSERT INTO compatibility_rules (rule_code, domain, title, description, condition_json, severity, recommended_action, is_active) VALUES ('FURN_SPACE_WIDTH', 'FURNITURE', 'Room & Desk Dimension Fit', 'Checks furniture/organizer width against stated room or desk dimensions.', '{"maxWidthCm":"context.availableWidthCm"}', 'INCOMPATIBLE', 'Select a narrower organizer or adjust desk clearance.', TRUE);
INSERT INTO compatibility_rules (rule_code, domain, title, description, condition_json, severity, recommended_action, is_active) VALUES ('FASH_SIZE_AVAIL', 'FASHION', 'Apparel & Footwear Size Match', 'Verifies requested size appears in product availableSizes attribute.', '{"sizeMatch":"context.size"}', 'WARNING', 'Confirm exact size on retailer page before purchase.', TRUE);
INSERT INTO compatibility_rules (rule_code, domain, title, description, condition_json, severity, recommended_action, is_active) VALUES ('SKIN_ACID_RETINOID', 'SKINCARE', 'AHA/BHA + Retinol Layering Caution', 'Flags using exfoliating acids and retinoids in the exact same evening step.', '{"conflict":["salicylic","retinol"]}', 'WARNING', 'Alternate nights and pair with morning SPF 50 sunscreen.', TRUE);
